    0.68 * danger(r1, 1.02 + 0.18 * vEst) +
    0.32 * danger(r0, 0.82 + 0.12 * vEst);

  const leftDanger =
    0.68 * danger(r3, 1.02 + 0.18 * vEst) +
    0.32 * danger(r4, 0.82 + 0.12 * vEst);

  const rightLat = lateral(r1, r0);
  const leftLat = lateral(r3, r4);
  const minLat = Math.min(leftLat, rightLat);

  const diagClose =
