    frontDanger > 0.025 ||
    frontRange < frontLook + 0.18 ||
    diagClose;

  const hardFront =
    boundaryHard ||
    frontRange < 0.62 ||
    (frontRange < 0.88 &&
     (r1 < 0.64 || r3 < 0.64));

  const urgent =
    hardFront ||
    boundaryBlock ||
    frontRange < 1.08 ||
    frontDanger > 0.38 ||
    minLat < 0.28 ||
    Math.abs(num(mem.yawRate, 0)) > 3.2;

  let leftScore =
    0.68 * openValue(rawRays[3]) +
    0.32 * openValue(rawRays[4]) -
    0.22 * leftDanger;

  let rightScore =
    0.68 * openValue(rawRays[1]) +
    0.32 * openValue(rawRays[0]) -
    0.22 * rightDanger;

