        mem.routeSide = side;
        mem.wallSide = -side;
        mem.wallTicks = 0;
        mem.hitDist = targetDist;
        mem.bestDist = targetDist;
        mem.noProg = 0;
        mem.clearTicks = 0;
        mem.stallTicks = 0;
        mem.sideSwapLock = 45;
        mem.leaveLock = 52;
        mem.escapeCooldown = 82;
