  if (vEst > 1.55) {
    base *= 0.60;
  } else if (vEst > 1.25) {
    base *= 0.78;
  }

  if (Math.abs(turn) > 0.52) {
    base *= 0.62;
  } else if (Math.abs(turn) > 0.38) {
    base *= 0.80;
  }

  if (Math.abs(num(mem.yawRate, 0)) > 2.8) {
    base *= 0.50;
  } else if (Math.abs(num(mem.yawRate, 0)) > 1.8) {
    base *= 0.72;
