  const targetErr = wrap(targetBearing - heading);

  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  const rays = [];
  for (let i = 0; i < 5; i++) {
    const fallback = i === 2 ? num(obs.distanceAhead, 10) : 10;
    rays[i] = clamp(num(rawRays[i], fallback), 0, 10);
  }
  const rayAngles = [-60, -30, 0, 30, 60];

  let yawRate = Number.isFinite(mem.yawRate) ? mem.yawRate : 0;
  if (Number.isFinite(mem.prevHeading) && Number.isFinite(mem.prevTime)) {
    const dt = now - mem.prevTime;
    if (dt > 0.01 && dt < 0.5) {
      const rawRate = clamp(wrap(heading - mem.prevHeading) / dt, -320, 320);
      yawRate += 0.26 * (rawRate - yawRate);
    }
  }
  mem.yawRate = clamp(yawRate, -280, 280);
  mem.prevHeading = heading;
  mem.prevTime = now;

  if (!Array.isArray(mem.obstacles)) mem.obstacles = [];
  if (!Array.isArray(mem.path)) mem.path = [];

  if (mem.targetIndex !== targetIndex || !Number.isFinite(mem.bestDist)) {
    mem.targetIndex = targetIndex;
    mem.bestDist = targetDist;
    mem.lastProgress = now;
    mem.posCheckX = x;
    mem.posCheckY = y;
    mem.stallCheckTime = now;
    mem.stallCount = 0;
    mem.loopCheckTime = now;
    mem.loopX = x;
    mem.loopY = y;
    mem.avoidSide = 0;
    mem.avoidStart = now;
    mem.clearSince = NaN;
    mem.navAbs = heading;
    mem.forceSide = 0;
    mem.forceSideUntil = 0;
    mem.recoveryCooldown = 0;
    mem.retreating = false;
  }

  // Retain recent sensor hits as a lightweight local map.
  if (!Number.isFinite(mem.mapTime) || now - mem.mapTime >= 0.12) {
    const hitAngles = [];
    for (let i = 0; i < 5; i++) {
      const r = rays[i];
      if (r >= 9.7 || r <= 0.12) continue;

      const a = (heading + rayAngles[i]) * Math.PI / 180;
      const px = x + r * Math.cos(a);
      const py = y + r * Math.sin(a);

      let nearest = -1;
      let nearestDist = 0.72;
      for (let j = mem.obstacles.length - 1; j >= 0; j--) {
        const p = mem.obstacles[j];
        const d = Math.hypot(px - p.x, py - p.y);
        if (d < nearestDist) {
          nearestDist = d;
          nearest = j;
        }
      }

      if (nearest >= 0) {
        const p = mem.obstacles[nearest];
        p.x = 0.66 * p.x + 0.34 * px;
        p.y = 0.66 * p.y + 0.34 * py;
        p.t = now;
      } else {
        mem.obstacles.push({ x: px, y: py, t: now });
      }
    }

    mem.obstacles = mem.obstacles.filter((p) =>
      now - p.t < 20 && Math.hypot(p.x - x, p.y - y) < 18
    );
    if (mem.obstacles.length > 140) {
      mem.obstacles.splice(0, mem.obstacles.length - 140);
    }
    mem.mapTime = now;
  }

  // Breadcrumbs are used to back out of a pocket or a persistent blockage.
  if (mem.path.length === 0) {
    mem.path.push({ x, y, h: heading, t: now });
  } else if (!mem.retreating && speed > 0.25) {
    const last = mem.path[mem.path.length - 1];
    if (Math.hypot(x - last.x, y - last.y) > 0.50) {
      mem.path.push({ x, y, h: heading, t: now });
      if (mem.path.length > 100) mem.path.splice(0, mem.path.length - 100);
    }
  }

  if (targetDist < mem.bestDist - 0.28) {
    mem.bestDist = targetDist;
    mem.lastProgress = now;
    mem.loopCheckTime = now;
    mem.loopX = x;
    mem.loopY = y;
  }

  // Reverse slowly along the previously travelled path when trapped.
  if (mem.retreating) {
    const retreatDist = Math.hypot(mem.retreatX - x, mem.retreatY - y);
    if (retreatDist < 0.68 || now - mem.retreatStart > 4.5) {
      mem.retreating = false;
      if (mem.retreatIndex >= 0 && mem.retreatIndex < mem.path.length) {
        mem.path = mem.path.slice(0, mem.retreatIndex + 1);
      } else {
        mem.path = [{ x, y, h: heading, t: now }];
      }

      let side = -num(mem.retreatSide, 0);
      if (!side) side = (num(mem.escapeCount, 0) % 2 === 0) ? 1 : -1;
      mem.escapeCount = num(mem.escapeCount, 0) + 1;
      mem.forceSide = side;
      mem.forceSideUntil = now + 7.0;
      mem.avoidSide = 0;
      mem.clearSince = NaN;
      mem.navAbs = heading;
      mem.bestDist = targetDist;
      mem.lastProgress = now;
      mem.stallCheckTime = now;
      mem.stallCount = 0;
      mem.loopCheckTime = now;
      mem.loopX = x;
      mem.loopY = y;
      mem.recoveryCooldown = now + 5.0;
    } else {
      const backBearing =
        Math.atan2(mem.retreatY - y, mem.retreatX - x) * 180 / Math.PI;
      const desiredBody = wrap(backBearing + 180);
      const err = wrap(desiredBody - heading);
      let reverseTarget = -0.48;
      if (Math.abs(err) > 132) reverseTarget = 0;

      let base = 0.42 * reverseTarget + 0.50 * (reverseTarget - speed);
      base = clamp(base, -0.52, 0.12);
      if (Math.abs(err) > 95 && speed > 0.05) base = Math.min(base, -0.22);

      let diff = 0.0060 * err - 0.0026 * mem.yawRate;
      diff = clamp(diff, -0.58, 0.58);
      return motors(base, diff);
    }
  }

  // Detect a stationary stall or circling without progress.
  let loopStall = false;
  if (now - num(mem.stallCheckTime, now) >= 1.2) {
    const elapsed = now - mem.stallCheckTime;
    const moved = Math.hypot(x - mem.posCheckX, y - mem.posCheckY);

    if (targetDist > 2.2 && moved < Math.max(0.20, 0.32 * elapsed)) {
      mem.stallCount = (mem.stallCount || 0) + 1;
    } else {
      mem.stallCount = 0;
    }

    mem.posCheckX = x;
    mem.posCheckY = y;
    mem.stallCheckTime = now;
  }

  if (now - num(mem.loopCheckTime, now) >= 5.0) {
    const loopMoved = Math.hypot(x - mem.loopX, y - mem.loopY);
    if (targetDist > 2.2 &&
        now - num(mem.lastProgress, now) > 6.0 &&
        loopMoved < 1.45) {
      loopStall = true;
    }
    mem.loopX = x;
    mem.loopY = y;
    mem.loopCheckTime = now;
  }

  if (targetDist > 2.2 &&
      now >= num(mem.recoveryCooldown, 0) &&
      ((mem.stallCount || 0) >= 2 || loopStall)) {
    let cut = mem.path.length - 2;
    if (cut < 0) cut = 0;

    while (cut > 0 &&
           Math.hypot(x - mem.path[cut].x, y - mem.path[cut].y) < 1.45) {
      cut--;
    }

    let rx = x;
    let ry = y;
    if (mem.path.length > 0) {
      rx = mem.path[cut].x;
      ry = mem.path[cut].y;
    }

    if (Math.hypot(rx - x, ry - y) < 0.75) {
      rx = x - 1.8 * Math.cos(heading * Math.PI / 180);
      ry = y - 1.8 * Math.sin(heading * Math.PI / 180);
      cut = -1;
    }

    mem.retreatX = rx;
    mem.retreatY = ry;
    mem.retreatIndex = cut;
    mem.retreatSide = mem.avoidSide ||
      ((num(mem.escapeCount, 0) % 2 === 0) ? 1 : -1);
    mem.retreatStart = now;
    mem.retreating = true;
    mem.recoveryCooldown = now + 5.0;
    mem.stallCount = 0;

    const backBearing =
      Math.atan2(ry - y, rx - x) * 180 / Math.PI;
    const desiredBody = wrap(backBearing + 180);
    const err = wrap(desiredBody - heading);
    const reverseTarget = Math.abs(err) > 132 ? 0 : -0.42;
    let base = 0.42 * reverseTarget + 0.50 * (reverseTarget - speed);
    base = clamp(base, -0.50, 0.12);
    let diff = clamp(0.0060 * err - 0.0026 * mem.yawRate, -0.58, 0.58);
    return motors(base, diff);
  }

  const leftOpen = 0.70 * rays[3] + 0.30 * rays[4];
  const rightOpen = 0.70 * rays[1] + 0.30 * rays[0];
  const openDiff = leftOpen - rightOpen;
  const minDiag = Math.min(rays[1], rays[3]);
  const blockedNow = rays[2] < 6.3 || minDiag < 3.1;

  if (blockedNow) {
    mem.clearSince = NaN;
    if (!mem.avoidSide) {
      let signal = openDiff + 0.55 * clamp(targetErr / 70, -1, 1);
      let side;
      if (now < num(mem.forceSideUntil, 0) &&
          Math.abs(num(mem.forceSide, 0)) > 0.5) {
        side = Math.sign(mem.forceSide);
      } else if (Math.abs(signal) > 0.20) {
        side = Math.sign(signal);
      } else {
        side = ((num(mem.escapeCount, 0) + targetIndex) % 2 === 0) ? 1 : -1;
      }
      mem.avoidSide = side;
      mem.avoidStart = now;
      mem.avoidCount = num(mem.avoidCount, 0) + 1;
    }
  } else if (mem.avoidSide) {
    if (rays[2] > 7.0 && minDiag > 4.0) {
      if (!Number.isFinite(mem.clearSince)) mem.clearSince = now;
      if (now - mem.clearSince > 0.55 &&
          now - num(mem.avoidStart, now) > 0.55) {
        mem.avoidSide = 0;
        mem.clearSince = NaN;
      }
    } else {
      mem.clearSince = NaN;
    }
  }

  const lookAhead = clamp(4.0 + 0.85 * Math.max(0, speed), 4.2, 6.0);
  const safeRadius = 0.68 + 0.055 * clamp(Math.abs(speed), 0, 2.4);
  const h = heading * Math.PI / 180;
  const ch = Math.cos(h);
  const sh = Math.sin(h);
  const points = [];

  for (let i = 0; i < mem.obstacles.length; i++) {
    const p = mem.obstacles[i];
    const age = now - p.t;
    if (age > 20) continue;

    const wx = p.x - x;
    const wy = p.y - y;
    const lx = wx * ch + wy * sh;
    const ly = -wx * sh + wy * ch;
    if (Math.hypot(lx, ly) > lookAhead + 1.0) continue;

    const weight = clamp(1 - 0.025 * Math.max(0, age), 0.48, 1);
    points.push({ x: lx, y: ly, w: weight });
  }

  // Include current returns even if the map update interval has not elapsed.
  for (let i = 0; i < 5; i++) {
    const r = rays[i];
    if (r >= 9.7 || r <= 0.12 || r > lookAhead + 1.0) continue;
    const a = rayAngles[i] * Math.PI / 180;
    points.push({
      x: r * Math.cos(a),
      y: r * Math.sin(a),
      w: 1
    });
  }

  let bestAlpha = clamp(targetErr, -180, 180);
  let bestCost = Infinity;
  let bestPathGap = Infinity;
  let bestRisk = 0;

  for (let alpha = -180; alpha <= 180; alpha += 5) {
    const ar = alpha * Math.PI / 180;
    const ux = Math.cos(ar);
    const uy = Math.sin(ar);
    let maxRisk = 0;
    let sumRisk = 0;
    let pathGap = Infinity;

    for (let j = 0; j < points.length; j++) {
      const p = points[j];
      const proj = p.x * ux + p.y * uy;
      if (proj <= 0.06 || proj > lookAhead + 0.25) continue;

      const lateral = Math.abs(-p.x * uy + p.y * ux);
      const nearWeight =
        0.52 + 0.48 * clamp(1 - proj / lookAhead, 0, 1);

      if (lateral < safeRadius) {
        const severity = clamp((safeRadius - lateral) / safeRadius, 0, 1);
        const risk = 178 * Math.pow(severity, 1.45) * nearWeight * p.w;
        maxRisk = Math.max(maxRisk, risk);
        sumRisk += risk;
      } else if (lateral < safeRadius + 0.42) {
        const q = (safeRadius + 0.42 - lateral) / 0.42;
        const risk = 15 * q * q * nearWeight * p.w;
        maxRisk = Math.max(maxRisk, risk);
        sumRisk += risk;
      }

      if (lateral < safeRadius + 0.26) {
        pathGap = Math.min(pathGap, Math.max(0.08, proj - 0.28));
      }
    }

    const worldA = (heading + alpha) * Math.PI / 180;
    const vx = Math.cos(worldA);
    const vy = Math.sin(worldA);
    let wallGap = Infinity;

    if (vx > 0.0001) wallGap = Math.min(wallGap, (39.15 - x) / vx);
    else if (vx < -0.0001) wallGap = Math.min(wallGap, (0.85 - x) / vx);
    if (vy > 0.0001) wallGap = Math.min(wallGap, (39.15 - y) / vy);
    else if (vy < -0.0001) wallGap = Math.min(wallGap, (0.85 - y) / vy);

    let wallRisk = 0;
    if (wallGap < lookAhead) {
      const closeness = clamp((lookAhead - wallGap) / lookAhead, 0, 1);
      wallRisk = 205 * Math.pow(closeness, 1.30);
      pathGap = Math.min(pathGap, Math.max(0.08, wallGap - 0.28));
    }

    const risk = maxRisk + 0.14 * Math.max(0, sumRisk - maxRisk);
    let cost = Math.abs(wrap(alpha - targetErr));
    cost += 0.035 * Math.abs(alpha);
    cost += risk + wallRisk;

    if (Number.isFinite(mem.navAbs)) {
      cost += 0.10 * Math.abs(wrap(worldA * 180 / Math.PI - mem.navAbs));
    }

    if (mem.avoidSide &&
        Math.abs(alpha) > 18 &&
        Math.sign(alpha) !== Math.sign(mem.avoidSide)) {
      cost += 16;
    }

    if (cost < bestCost) {
      bestCost = cost;
      bestAlpha = alpha;
      bestPathGap = pathGap;
      bestRisk = risk + wallRisk;
    }
  }

  const desiredWorld = wrap(heading + bestAlpha);
  if (!Number.isFinite(mem.navAbs)) {
    mem.navAbs = desiredWorld;
  } else {
    const urgent =
      rays[2] < 3.0 ||
      minDiag < 1.6 ||
      bestPathGap < 1.4 ||
      bestRisk > 55;
    const gain = urgent ? 0.66 : (blockedNow ? 0.50 : 0.38);
    const maxStep = urgent ? 52 : 36;
    const delta = wrap(desiredWorld - mem.navAbs);
    mem.navAbs = wrap(mem.navAbs + clamp(gain * delta, -maxStep, maxStep));
  }

  const steerErr = wrap(mem.navAbs - heading);
  const forwardGap = Math.min(rays[2], rays[1] + 0.40, rays[3] + 0.40);

  let targetSpeed = Math.min(
    2.15,
    0.80 * Math.sqrt(Math.max(0, forwardGap - 0.60))
  );

  if (Number.isFinite(bestPathGap)) {
    const pathSpeed =
      0.78 * Math.sqrt(Math.max(0, bestPathGap - 0.48));
    targetSpeed = Math.min(targetSpeed, pathSpeed);
  }

  const turnFactor =
    1 - 0.40 * clamp((Math.abs(steerErr) - 20) / 105, 0, 1);
  targetSpeed *= turnFactor;

  if (Math.abs(targetErr) > 125) targetSpeed = Math.min(targetSpeed, 0.65);
  if (targetDist < 4.2) {
    targetSpeed = Math.min(
      targetSpeed,
      0.88 * Math.sqrt(Math.max(0, targetDist - 0.28))
    );
  }
  if (forwardGap < 1.15 && Math.abs(steerErr) > 35) {
    targetSpeed = Math.min(targetSpeed, 0.22);
  }
  if (Math.min(rays[0], rays[4]) < 0.75) {
    targetSpeed = Math.min(targetSpeed, 0.38);
  }
  if (rays[2] < 0.42 && speed > 0.08) targetSpeed = -0.18;

  let base = 0.42 * targetSpeed + 0.50 * (targetSpeed - speed);
  base = clamp(base, -0.58, 0.90);

  if (rays[2] < 0.62 && speed > 0.10) {
    base = Math.min(base, -0.34);
  }

  if (targetSpeed > 0.20 &&
      Math.abs(speed) < 0.10 &&
      base > 0 &&
      forwardGap > 1.4 &&
      Math.abs(steerErr) < 60) {
    base = Math.max(base, 0.24);
  }

  let wheelDiff = 0.0058 * steerErr - 0.0026 * mem.yawRate;
  wheelDiff = clamp(wheelDiff, -0.64, 0.64);

  return motors(base, wheelDiff);
}

function act(obs, mem) {
  mem = mem || {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };

  const now = num(obs.t, 0);
  const x = num(obs.x, 20);
  const y = num(obs.y, 20);
  const heading = num(obs.heading, 0);
  const speed = num(obs.speed, 0);
  const targetIndex = Math.floor(num(obs.targetIndex, 0));

  let tx = num(obs.targetX, NaN);
  let ty = num(obs.targetY, NaN);
  if ((!Number.isFinite(tx) || !Number.isFinite(ty)) &&
      Array.isArray(obs.targets) && obs.targets[targetIndex] != null) {
    const q = obs.targets[targetIndex];
    if (Array.isArray(q)) {
      if (!Number.isFinite(tx)) tx = num(q[0], NaN);
      if (!Number.isFinite(ty)) ty = num(q[1], NaN);
    } else {
      if (!Number.isFinite(tx)) tx = num(q.x, NaN);
      if (!Number.isFinite(ty)) ty = num(q.y, NaN);
    }
  }
  if (!Number.isFinite(tx)) tx = num(obs.goalX, x);
  if (!Number.isFinite(ty)) ty = num(obs.goalY, y);

  const dx = tx - x;
  const dy = ty - y;
  const targetDist = Math.hypot(dx, dy);
  const targetBearing = targetDist > 0.001
    ? Math.atan2(dy, dx) * 180 / Math.PI
    : heading;
  const targetErr = wrap(targetBearing - heading);

  const rawRays = Array.isArray(obs.rays) ? obs.rays : [];
  const rays = [];
  for (let i = 0; i < 5; i++) {
    const fallback = i === 2 ? num(obs.distanceAhead, 10) : 10;
    rays[i] = clamp(num(rawRays[i], fallback), 0, 10);
  }
  const rayAngles = [-60, -30, 0, 30, 60];

  let yawRate = Number.isFinite(mem.yawRate) ? mem.yawRate : 0;
  if (Number.isFinite(mem.prevHeading) && Number.isFinite(mem.prevTime)) {
    const dt = now - mem.prevTime;
    if (dt > 0.01 && dt < 0.5) {
      const rawRate = clamp(wrap(heading - mem.prevHeading) / dt, -320, 320);
      yawRate += 0.25 * (rawRate - yawRate);
    }
  }
  mem.yawRate = clamp(yawRate, -280, 280);
  mem.prevHeading = heading;
  mem.prevTime = now;

  if (!Array.isArray(mem.hits)) mem.hits = [];
  if (mem.targetIndex !== targetIndex || !Number.isFinite(mem.bestDist)) {
    mem.targetIndex = targetIndex;
    mem.bestDist = targetDist;
    mem.lastProgress = now;
    mem.navWorld = heading;
    mem.avoidSide = 0;
    mem.avoidStart = now;
    mem.bypassWorld = NaN;
    mem.clearSince = NaN;
    mem.escapeWorld = NaN;
    mem.escapeUntil = 0;
    mem.recoveryCooldown = 0;
    mem.stallCheckTime = now;
    mem.stallX = x;
    mem.stallY = y;
    mem.stallCount = 0;
    mem.loopCheckTime = now;
    mem.loopX = x;
    mem.loopY = y;
  }

  if (targetDist < mem.bestDist - 0.30) {
    mem.bestDist = targetDist;
    mem.lastProgress = now;
  }

  const hRad = heading * Math.PI / 180;
  const ch = Math.cos(hRad);
  const sh = Math.sin(hRad);

  // Remember recent ray endpoints, but let stale returns fade out.
  if (!Number.isFinite(mem.mapTime) || now - mem.mapTime >= 0.12) {
    for (let i = 0; i < 5; i++) {
      const d = rays[i];
      if (d >= 9.65 || d <= 0.12) continue;

      const a = (heading + rayAngles[i]) * Math.PI / 180;
      const px = x + d * Math.cos(a);
      const py = y + d * Math.sin(a);

      let nearest = -1;
      let nearestDist = 0.78;
      for (let j = mem.hits.length - 1; j >= 0; j--) {
        const p = mem.hits[j];
        const q = Math.hypot(px - p.x, py - p.y);
        if (q < nearestDist) {
          nearestDist = q;
          nearest = j;
        }
      }

      if (nearest >= 0) {
        const p = mem.hits[nearest];
        p.x = 0.58 * p.x + 0.42 * px;
        p.y = 0.58 * p.y + 0.42 * py;
        p.t = now;
      } else {
        mem.hits.push({ x: px, y: py, t: now });
      }
    }

    mem.hits = mem.hits.filter((p) =>
      now - p.t < 7.0 && Math.hypot(p.x - x, p.y - y) < 11.5
    );
    if (mem.hits.length > 110) {
      mem.hits.splice(0, mem.hits.length - 110);
    }
    mem.mapTime = now;
  }

  const leftOpen = 0.68 * rays[3] + 0.32 * rays[4];
  const rightOpen = 0.68 * rays[1] + 0.32 * rays[0];
  const minDiag = Math.min(rays[1], rays[3]);
  const frontClear = Math.min(rays[2], rays[1] + 0.45, rays[3] + 0.45);

  const chooseSide = () => {
    const d = leftOpen - rightOpen;
    if (Math.abs(d) > 0.38) return d > 0 ? 1 : -1;
    if (Math.abs(targetErr) > 16) return targetErr > 0 ? 1 : -1;
    return ((num(mem.avoidCount, 0) + targetIndex) % 2 === 0) ? 1 : -1;
  };

  if (frontClear < 4.45 || minDiag < 2.75) {
    mem.clearSince = NaN;
    if (!mem.avoidSide) {
      mem.avoidSide = chooseSide();
      mem.avoidStart = now;
      mem.avoidCount = num(mem.avoidCount, 0) + 1;

      const baseBearing = Math.abs(targetErr) < 95 ? targetBearing : heading;
      mem.bypassWorld = wrap(baseBearing + 58 * mem.avoidSide);
    }
  } else if (mem.avoidSide) {
    if (frontClear > 6.15 && minDiag > 4.35) {
      if (!Number.isFinite(mem.clearSince)) mem.clearSince = now;
      if (now - mem.clearSince > 0.55 &&
          now - num(mem.avoidStart, now) > 0.75) {
        mem.avoidSide = 0;
        mem.clearSince = NaN;
      }
    } else {
      mem.clearSince = NaN;
    }
  }

  // Detect being stationary or looping, then try the other side without backing up.
  let escapeNeeded = false;
  if (now - num(mem.stallCheckTime, now) >= 1.5) {
    const moved = Math.hypot(x - mem.stallX, y - mem.stallY);
    if (targetDist > 1.7 && moved < 0.42 &&
        now - num(mem.lastProgress, now) > 1.3) {
      mem.stallCount = num(mem.stallCount, 0) + 1;
    } else {
      mem.stallCount = 0;
    }
    if (mem.stallCount >= 2) escapeNeeded = true;

    mem.stallCheckTime = now;
    mem.stallX = x;
    mem.stallY = y;
  }

  if (now - num(mem.loopCheckTime, now) >= 4.2) {
    const moved = Math.hypot(x - mem.loopX, y - mem.loopY);
    if (targetDist > 2.1 &&
        now - num(mem.lastProgress, now) > 4.5 &&
        moved < 1.25) {
      escapeNeeded = true;
    }
    mem.loopCheckTime = now;
    mem.loopX = x;
    mem.loopY = y;
  }

  if (escapeNeeded && now >= num(mem.recoveryCooldown, 0) && targetDist > 1.7) {
    let side = mem.avoidSide ? -mem.avoidSide : chooseSide();
    if (!side) side = 1;
    mem.avoidSide = side;
    mem.avoidStart = now;
    mem.clearSince = NaN;

    const baseBearing = Math.abs(targetErr) < 95 ? targetBearing : heading;
    mem.bypassWorld = wrap(baseBearing + 66 * side);
    mem.escapeWorld = wrap(heading + 92 * side);
    mem.escapeUntil = now + 0.80;
    mem.navWorld = mem.escapeWorld;
    mem.recoveryCooldown = now + 3.6;
    mem.lastProgress = now;
    mem.bestDist = targetDist;
    mem.stallCount = 0;
  }

