  const safe = 0.70 + 0.075 * clamp(Math.abs(speed), 0, 2.4);
  const points = [];

  const addPoint = (px, py, weight) => {
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      if (Math.hypot(px - p.x, py - p.y) < 0.48) {
        p.w = Math.max(p.w, weight);
        return;
      }
    }
    points.push({ x: px, y: py, w: weight });
  };

  for (let i = 0; i < mem.hits.length; i++) {
    const p = mem.hits[i];
    const age = now - p.t;
    if (age > 6.7) continue;

    const wx = p.x - x;
    const wy = p.y - y;
    const lx = wx * ch + wy * sh;
    const ly = -wx * sh + wy * ch;
    if (Math.hypot(lx, ly) > lookAhead + 1.5) continue;

    addPoint(lx, ly, clamp(1 - age / 7.2, 0.18, 1));
  }

  for (let i = 0; i < 5; i++) {
    const d = rays[i];
    if (d >= 9.65 || d <= 0.12 || d > lookAhead + 1.4) continue;
    const a = rayAngles[i] * Math.PI / 180;
    addPoint(d * Math.cos(a), d * Math.sin(a), 1);
  }

  let preferredWorld = targetBearing;
  if (now < num(mem.escapeUntil, 0) && Number.isFinite(mem.escapeWorld)) {
    preferredWorld = mem.escapeWorld;
  } else if (mem.avoidSide && Number.isFinite(mem.bypassWorld)) {
    preferredWorld = mem.bypassWorld;
  }
  const preferredErr = wrap(preferredWorld - heading);

  let bestAlpha = preferredErr;
  let bestCost = Infinity;
  let bestGap = lookAhead + 0.75;
  let bestRisk = 0;

  for (let alpha = -180; alpha <= 180; alpha += 5) {
    const ar = alpha * Math.PI / 180;
    const ux = Math.cos(ar);
    const uy = Math.sin(ar);

    let maxRisk = 0;
    let sumRisk = 0;
    let pathGap = lookAhead + 0.75;

    for (let j = 0; j < points.length; j++) {
      const p = points[j];
      const proj = p.x * ux + p.y * uy;
      if (proj <= 0.12 || proj > lookAhead + 0.9) continue;

      const lateral = Math.abs(-p.x * uy + p.y * ux);
      const beyond = Math.max(0, proj - lookAhead);
      const dist = Math.hypot(lateral, beyond);
      const nearWeight =
        0.78 + 0.22 * clamp(1 - proj / lookAhead, 0, 1);

      const inner = clamp((safe - dist) / safe, 0, 1);
      const outer = clamp((safe + 0.68 - dist) / 0.68, 0, 1);
      const risk =
        (165 * Math.pow(inner, 1.4) + 24 * outer * outer) *
        nearWeight * p.w;

      maxRisk = Math.max(maxRisk, risk);
      sumRisk += risk;

      if (proj < lookAhead + 0.2 && lateral < safe + 0.16) {
        pathGap = Math.min(pathGap, Math.max(0, proj - 0.22));
      }
    }

    let riskCost = maxRisk + Math.min(70, 0.14 * Math.max(0, sumRisk - maxRisk));

    const worldA = wrap(heading + alpha) * Math.PI / 180;
    const vx = Math.cos(worldA);
    const vy = Math.sin(worldA);
    let wallGap = Infinity;

    if (vx > 0.0001) wallGap = Math.min(wallGap, (39.2 - x) / vx);
    else if (vx < -0.0001) wallGap = Math.min(wallGap, (0.8 - x) / vx);
    if (vy > 0.0001) wallGap = Math.min(wallGap, (39.2 - y) / vy);
    else if (vy < -0.0001) wallGap = Math.min(wallGap, (0.8 - y) / vy);

    let wallRisk = 0;
    if (wallGap < lookAhead + 0.9) {
      const q = clamp((lookAhead + 0.9 - wallGap) / (lookAhead + 0.9), 0, 1);
      wallRisk = 215 * Math.pow(q, 1.3);
      pathGap = Math.min(pathGap, Math.max(0, wallGap - 0.20));
    }

    let cost = 0.66 * Math.abs(wrap(alpha - preferredErr));
    cost += 0.025 * Math.abs(alpha);
    cost += riskCost + wallRisk;

    if (Number.isFinite(mem.navWorld)) {
      cost += 0.08 * Math.abs(wrap(worldA * 180 / Math.PI - mem.navWorld));
    }

    if (mem.avoidSide && Math.abs(alpha) > 18 &&
        Math.sign(alpha) !== Math.sign(mem.avoidSide)) {
      const age = now - num(mem.avoidStart, now);
      cost += 30 * clamp(1 - age / 4.5, 0.35, 1);
    }

    if (cost < bestCost) {
      bestCost = cost;
      bestAlpha = alpha;
      bestGap = pathGap;
      bestRisk = riskCost + wallRisk;
    }
  }

  const desiredWorld = wrap(heading + bestAlpha);
  if (!Number.isFinite(mem.navWorld)) {
    mem.navWorld = desiredWorld;
  } else {
    const urgent = frontClear < 2.0 || bestGap < 1.45 || bestRisk > 65;
    const delta = wrap(desiredWorld - mem.navWorld);
    const gain = urgent ? 0.56 : 0.38;
    const maxStep = urgent ? 14 : 8;
    mem.navWorld = wrap(mem.navWorld + clamp(gain * delta, -maxStep, maxStep));
  }

  const steerErr = wrap(mem.navWorld - heading);
  let desiredSpeed = Math.min(
    2.0,
    0.82 * Math.sqrt(Math.max(0, bestGap - 0.58)),
    0.78 * Math.sqrt(Math.max(0, frontClear - 0.62))
  );

  const turnFactor =
    1 - 0.42 * clamp((Math.abs(steerErr) - 18) / 92, 0, 1);
  desiredSpeed *= turnFactor;

  if (Math.abs(targetErr) > 122) desiredSpeed = Math.min(desiredSpeed, 0.62);
  if (now < num(mem.escapeUntil, 0)) desiredSpeed = Math.min(desiredSpeed, 0.72);

  if (targetDist < 4.0) {
    desiredSpeed = Math.min(
      desiredSpeed,
      0.86 * Math.sqrt(Math.max(0, targetDist - 0.42))
    );
  }
  if (targetDist < 1.05) {
    desiredSpeed = Math.min(desiredSpeed, 0.34);
  }
  if (frontClear < 0.72) desiredSpeed = Math.min(desiredSpeed, 0.20);
  if (Math.min(rays[0], rays[4]) < 0.65) {
    desiredSpeed = Math.min(desiredSpeed, 0.42);
  }

  let base = 0.42 * desiredSpeed + 0.50 * (desiredSpeed - speed);
  base = clamp(base, -0.22, 0.90);

  if (targetDist > 1.05 && desiredSpeed > 0.16 && speed < 0.10) {
    base = Math.max(base, 0.20);
  }
  if (base < 0 && frontClear > 0.82) base = 0.08;
  if (speed <= 0.04 && desiredSpeed > 0.12) base = Math.max(base, 0.16);
  if (frontClear < 0.52 && speed > 0.35) base = Math.min(base, -0.16);

  let diff = 0.0053 * clamp(steerErr, -132, 132) - 0.0022 * mem.yawRate;
  diff = clamp(diff, -0.58, 0.58);

  let left = base - 0.5 * diff;
  let right = base + 0.5 * diff;
  const scale = Math.max(1, Math.abs(left), Math.abs(right));
  left = clamp(left / scale, -1, 1);
  right = clamp(right / scale, -1, 1);

  return { left, right };
}

function act(obs, mem) {
  mem = mem || {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };

  const now = num(obs.t, 0);
  const x = num(obs.x, 20);
  const y = num(obs.y, 20);
  const heading = num(obs.heading, 0);
  const speed = num(obs.speed, 0);
  const targetIndex = Math.floor(num(obs.targetIndex, 0));

  let tx = num(obs.targetX, NaN);
  let ty = num(obs.targetY, NaN);
  if ((!Number.isFinite(tx) || !Number.isFinite(ty)) &&
      Array.isArray(obs.targets) && obs.targets[targetIndex] != null) {
    const q = obs.targets[targetIndex];
    if (Array.isArray(q)) {
      if (!Number.isFinite(tx)) tx = num(q[0], NaN);
      if (!Number.isFinite(ty)) ty = num(q[1], NaN);
    } else {
      if (!Number.isFinite(tx)) tx = num(q.x, NaN);
      if (!Number.isFinite(ty)) ty = num(q.y, NaN);
    }
  }
