    mem.targetIndex = targetIndex;
    mem.bestDist = targetDist;
    mem.lastProgress = now;
    mem.navWorld = targetBearing;
    mem.routeX = tx;
    mem.routeY = ty;
    mem.planTime = NaN;
    mem.escapeUntil = 0;
    mem.escapeSide = 0;
    mem.recoveryCooldown = 0;
    mem.badUntil = 0;
    mem.stallCheckTime = now;
    mem.stallX = x;
    mem.stallY = y;
    mem.stallCount = 0;
    mem.loopCheckTime = now;
    mem.loopX = x;
    mem.loopY = y;
  }

