    }

    mem.hits = mem.hits.filter((p) =>
      now - p.t < 55 && Math.hypot(p.x - x, p.y - y) < 18
    );
    if (mem.hits.length > 240) {
      mem.hits.sort((a, b) => b.t - a.t);
      mem.hits.splice(240);
    }
    mem.badSpots = mem.badSpots.filter((p) =>
      now - p.t < 35 && Math.hypot(p.x - x, p.y - y) < 16
