    if (targetDist > 1.5 &&
        moved < 0.38 &&
        now - num(mem.lastProgress, now) > 1.5) {
      mem.stallCount = num(mem.stallCount, 0) + 1;
    } else {
      mem.stallCount = 0;
    }
    mem.stallX = x;
    mem.stallY = y;
    mem.stallCheckTime = now;
  }

  if (now - num(mem.loopCheckTime, now) >= 4.5) {
    const moved = Math.hypot(x - mem.loopX, y - mem.loopY);
    if (targetDist > 1.8 &&
        now - num(mem.lastProgress, now) > 4.5 &&
        moved < 1.55) {
      loopStall = true;
    }
    mem.loopX = x;
    mem.loopY = y;
    mem.loopCheckTime = now;
  }

  const leftOpen = 0.70 * rays[3] + 0.30 * rays[4];
  const rightOpen = 0.70 * rays[1] + 0.30 * rays[0];

  let seedBearing = targetBearing;
  if (Number.isFinite(mem.routeX) && Number.isFinite(mem.routeY)) {
    const rx = mem.routeX - x;
    const ry = mem.routeY - y;
    if (Math.hypot(rx, ry) > 0.2) seedBearing = Math.atan2(ry, rx) * 180 / Math.PI;
