      const hardR = 0.61;
      const softR = 1.38;
      const ix0 = Math.max(0, Math.floor((p.x - softR) / gridStep));
      const ix1 = Math.min(gridN - 1, Math.floor((p.x + softR) / gridStep));
      const iy0 = Math.max(0, Math.floor((p.y - softR) / gridStep));
      const iy1 = Math.min(gridN - 1, Math.floor((p.y + softR) / gridStep));

      for (let iy = iy0; iy <= iy1; iy++) {
        const cy = (iy + 0.5) * gridStep;
        for (let ix = ix0; ix <= ix1; ix++) {
          const cx = (ix + 0.5) * gridStep;
          const d = Math.hypot(cx - p.x, cy - p.y);
          const id = iy * gridN + ix;
