      if (age > 35) continue;
      const radius = 2.2;
      const ix0 = Math.max(0, Math.floor((p.x - radius) / gridStep));
      const ix1 = Math.min(gridN - 1, Math.floor((p.x + radius) / gridStep));
      const iy0 = Math.max(0, Math.floor((p.y - radius) / gridStep));
      const iy1 = Math.min(gridN - 1, Math.floor((p.y + radius) / gridStep));

