        const cy = (iy + 0.5) * gridStep;
        for (let ix = ix0; ix <= ix1; ix++) {
          const cx = (ix + 0.5) * gridStep;
          const d = Math.hypot(cx - p.x, cy - p.y);
          if (d < radius) {
            const q = (radius - d) / radius;
            const id = iy * gridN + ix;
            penalty[id] = Math.min(3, penalty[id] + 1.7 * q * q);
          }
        }
      }
