        const key = heapKeys[0];
        const lastNode = heapNodes.pop();
        const lastKey = heapKeys.pop();

        if (heapNodes.length > 0) {
          let i = 0;
          while (true) {
            const l = i * 2 + 1;
            const r = l + 1;
            if (l >= heapNodes.length) break;
            let c = l;
            if (r < heapNodes.length && heapKeys[r] < heapKeys[l]) c = r;
            if (heapKeys[c] >= lastKey) break;
            heapNodes[i] = heapNodes[c];
            heapKeys[i] = heapKeys[c];
            i = c;
          }
          heapNodes[i] = lastNode;
          heapKeys[i] = lastKey;
        }
        return [node, key];
      };

