      heapPush(start, heuristic(start));
      let bestNode = start;
      let bestH = heuristic(start);
      let found = false;
      let expanded = 0;

      while (heapNodes.length > 0 && expanded < gridLen) {
        const item = heapPop();
        const cur = item[0];
        const f = item[1];
        if (closed[cur]) continue;
        if (f > gScore[cur] + heuristic(cur) + 1e-7) continue;

        closed[cur] = 1;
        expanded++;

        const hcur = heuristic(cur);
