  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = cx + dx, ny = cy + dy;
      if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
        const idx = ny * W + nx;
        if (mem.map[idx] === 2) mem.map[idx] = 1;
      }
    }
  }

  if (mem.calib) {
    const h = mem.head;
    for (let i = 0; i < 5; i++) {
      let d = r[i];
      if (d < 0.1) continue;
      const ang = (h + SANG[i]) * PIDEG;
      const dx = Math.cos(ang), dy = Math.sin(ang);
      const steps = Math.min(40, Math.floor(d / RES));
      for (let s = 1; s <= steps; s++) {
        const px = obs.x + dx * s * RES;
        const py = obs.y + dy * s * RES;
        const gx = Math.floor(px / RES), gy = Math.floor(py / RES);
        if (gx < 0 || gx >= W || gy < 0 || gy >= H) continue;
        const idx = gy * W + gx;
        if (s < steps) {
          if (mem.map[idx] !== 2) mem.map[idx] = 1;
        } else {
          if (d < 9.5) mem.map[idx] = 2;
          else mem.map[idx] = 1;
        }
      }
    }
  }

  const distT = Math.hypot(obs.targetX - obs.x, obs.targetY - obs.y);

  if (mem.lastBase > 0.3 && Math.abs(obs.speed) < 0.1) mem.stuckTime += dt;
  else mem.stuckTime = Math.max(0, mem.stuckTime - dt * 1.5);

  if (mem.recovery) {
    const rec = mem.recovery;
    if (t >= rec.until) {
      if (rec.phase === 'back') { rec.phase = 'turn'; rec.until = t + 0.5; }
      else if (rec.phase === 'turn') { rec.phase = 'fwd'; rec.until = t + 0.6; }
      else { mem.recovery = null; mem.path = null; }
    }
    if (mem.recovery) {
      let left, right;
      if (rec.phase === 'back') { left = -0.5; right = -0.5; }
      else if (rec.phase === 'turn') { left = -0.5 * rec.dir; right = 0.5 * rec.dir; }
      else { left = 0.5; right = 0.5; }
      mem.lastCmd = { left: left, right: right };
      mem.lastBase = 0.5;
      return { left: left, right: right };
    }
  }

  if (mem.stuckTime > 1.8) {
    const dir = leftNear >= rightNear ? 1 : -1;
    mem.recovery = { phase: 'back', until: t + 0.4, dir: dir };
    mem.stuckTime = 0;
    mem.path = null;
  }

  let needPlan = false;
  if (!mem.path) needPlan = true;
  else if (t - mem.pathT > 0.7) needPlan = true;
  if (needPlan) {
    const path = planPath(obs.x, obs.y, obs.targetX, obs.targetY, mem);
    mem.path = path;
    mem.pathT = t;
  }

  let tx = obs.targetX, ty = obs.targetY;
  if (mem.path && mem.path.length > 0 && distT > 1.2) {
    let minD = 1e9, minI = 0;
    for (let i = 0; i < mem.path.length; i++) {
      const idx = mem.path[i];
      const px = (idx % W + 0.5) * RES;
      const py = (Math.floor(idx / W) + 0.5) * RES;
      const d2 = (px - obs.x) * (px - obs.x) + (py - obs.y) * (py - obs.y);
      if (d2 < minD) { minD = d2; minI = i; }
    }
    let acc = 0;
    let prevX = obs.x, prevY = obs.y;
    let found = false;
    for (let i = minI; i < mem.path.length; i++) {
      const idx = mem.path[i];
      const px = (idx % W + 0.5) * RES;
      const py = (Math.floor(idx / W) + 0.5) * RES;
      acc += Math.hypot(px - prevX, py - prevY);
      if (acc >= 1.0) { tx = px; ty = py; found = true; break; }
      prevX = px; prevY = py;
    }
    if (!found) { tx = prevX; ty = prevY; }
  }

  if (front < 0.3 && obs.speed > -0.1) {
    const left = -0.5, right = -0.5;
    mem.lastCmd = { left: left, right: right };
    mem.lastBase = -0.5;
    return { left: left, right: right };
  }

  const bearing = Math.atan2(ty - obs.y, tx - obs.x) * 180 / Math.PI;
  const err = norm(bearing - mem.head);

  let steer = err * 1.0;
  let avoid = 0;
  for (let i = 0; i < 5; i++) {
    const d = r[i];
    if (d < 1.5) {
      const strength = (1.5 - d) / 1.5;
      avoid += -Math.sin(SANG[i] * PIDEG) * strength * 70;
    }
  }
  if (leftNear < 1.0) avoid -= (1.0 - leftNear) * 60;
  if (rightNear < 1.0) avoid += (1.0 - rightNear) * 60;
  if (front < 1.2) {
    let diff = leftNear - rightNear;
    if (Math.abs(diff) < 0.2) diff = err >= 0 ? 1 : -1;
    avoid += clamp(diff, -1, 1) * 70 * (1.2 - front) / 1.2;
  }
  steer = clamp(steer + avoid, -150, 150);
  const sDes = clamp(steer / 60, -1, 1);
  mem.steer = mem.steer * 0.7 + sDes * 0.3;
  const s = clamp(mem.steer, -1, 1);

  let base = 1.0;
  if (Math.abs(err) > 45) base *= 0.7;
  if (Math.abs(err) > 90) base *= 0.5;
  if (front < 2.0) base *= Math.max(0.15, (front - 0.4) / 1.6);
  if (leftNear < 0.8 || rightNear < 0.8) base *= 0.8;
  if (distT < 1.5) base *= 0.7;
  if (distT < 1.0) base *= 0.5;
  if (front < 0.55) base = Math.min(base, 0.05);
  if (front < 0.4) base = Math.min(base, -0.1);
  base = clamp(base, -0.2, 1.0);

  function dz(v) {
    if (v > 0 && v < 0.15) return 0.15;
    if (v < 0 && v > -0.15) return -0.15;
    return v;
  }

  let left = base - s * 0.8;
  let right = base + s * 0.8;
  left = clamp(dz(left), -1, 1);
  right = clamp(dz(right), -1, 1);
  mem.lastCmd = { left: left, right: right };
  mem.lastBase = base;
  return { left: left, right: right };
}
